import Foundation
import CoreLocation
import SwiftUI

/// One city of the landmark pack (`design/citypack.json`, generated by `design/citypack.py`).
struct PackCity: Codable, Sendable, Equatable {
    let key: String
    let name: String
    let local: String
    let fontScale: Double
    let country: String
    let lat: Double
    let lon: Double
    let radiusKm: Double
    let landmark: String
    let path: String

    var coordinate: CLLocationCoordinate2D { .init(latitude: lat, longitude: lon) }
    /// "DUBAI · 25.20° N 55.27° E": English name when the local name differs, else the country.
    var subline: String {
        "\((local == name ? country : name).uppercased()) · \(CardText.coordinate(coordinate))"
    }
}

/// The bundled city pack, loaded once. Matching is purely local.
struct CityPack: Codable, Sendable {
    let version: Int
    let box: [Double]
    let ground: Double
    let cities: [PackCity]

    static let shared: CityPack = load() ?? CityPack(version: 0, box: [200, 60], ground: 58, cities: [])

    static func load(bundle: Bundle = .main) -> CityPack? {
        guard let url = bundle.url(forResource: "citypack", withExtension: "json"),
              let data = try? Data(contentsOf: url) else { return nil }
        return try? JSONDecoder().decode(CityPack.self, from: data)
    }

    /// Nearest city whose centre is within its radius (boundary inclusive).
    func match(_ c: CLLocationCoordinate2D) -> PackCity? {
        var best: (PackCity, Double)?
        for city in cities {
            let d = Self.haversineKm(c, city.coordinate)
            if d <= city.radiusKm, d < (best?.1 ?? .infinity) { best = (city, d) }
        }
        return best?.0
    }

    static func haversineKm(_ a: CLLocationCoordinate2D, _ b: CLLocationCoordinate2D) -> Double {
        let r = 6371.0088, rad = Double.pi / 180
        let dLat = (b.latitude - a.latitude) * rad, dLon = (b.longitude - a.longitude) * rad
        let h = sin(dLat / 2) * sin(dLat / 2) + cos(a.latitude * rad) * cos(b.latitude * rad) * sin(dLon / 2) * sin(dLon / 2)
        return 2 * r * asin(min(1, sqrt(h)))
    }
}

/// Minimal SVG path-data parser for absolute M L H V C Q Z. Unknown commands or bad
/// numbers stop parsing; whatever was parsed so far is returned. Never traps.
enum SVGPath {
    static func parse(_ d: String) -> Path {
        let tokens = Array(d)
        var i = 0
        var path = Path()
        var cur = CGPoint.zero, start = CGPoint.zero
        var hasPoint = false

        func skipSeparators() { while i < tokens.count, tokens[i] == " " || tokens[i] == "," || tokens[i].isNewline || tokens[i] == "\t" { i += 1 } }
        func number() -> CGFloat? {
            skipSeparators()
            var s = ""
            if i < tokens.count, tokens[i] == "-" || tokens[i] == "+" { s.append(tokens[i]); i += 1 }
            var dot = false
            while i < tokens.count {
                let ch = tokens[i]
                if ch.isASCII, ch.isNumber { s.append(ch); i += 1 }
                else if ch == ".", !dot { dot = true; s.append(ch); i += 1 }
                else { break }
            }
            guard let v = Double(s), v.isFinite else { return nil }
            return CGFloat(v)
        }
        func point() -> CGPoint? { guard let x = number(), let y = number() else { return nil }; return CGPoint(x: x, y: y) }

        loop: while true {
            skipSeparators()
            guard i < tokens.count else { break }
            let cmd = tokens[i]; i += 1
            switch cmd {
            case "M":
                guard let p = point() else { break loop }
                path.move(to: p); cur = p; start = p; hasPoint = true
            case "L":
                guard hasPoint, let p = point() else { break loop }
                path.addLine(to: p); cur = p
            case "H":
                guard hasPoint, let x = number() else { break loop }
                cur = CGPoint(x: x, y: cur.y); path.addLine(to: cur)
            case "V":
                guard hasPoint, let y = number() else { break loop }
                cur = CGPoint(x: cur.x, y: y); path.addLine(to: cur)
            case "C":
                guard hasPoint, let c1 = point(), let c2 = point(), let p = point() else { break loop }
                path.addCurve(to: p, control1: c1, control2: c2); cur = p
            case "Q":
                guard hasPoint, let c = point(), let p = point() else { break loop }
                path.addQuadCurve(to: p, control: c); cur = p
            case "Z", "z":
                guard hasPoint else { break loop }
                path.closeSubpath(); cur = start
            default:
                break loop
            }
        }
        return path
    }
}
